import torch


def gen_inputs(ctx, device):
    if "n__shape" not in ctx:
        return {}
    shape = tuple(ctx["n__shape"])
    n = torch.randint(0, 10, shape, device="cpu").to(torch.int32).to(device)
    return {"n": n}


def run_correctness(x, n):
    output = torch.special.shifted_chebyshev_polynomial_v(x.float(), n)
    return output.to(x.dtype)


def run(x, n):
    return torch.special.shifted_chebyshev_polynomial_v(x, n)
